(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.32)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*10 + Math.cos(sy*0.02+t*0.35)*7;
  const w2y = Math.cos(sy*0.022+t*0.38)*9 + Math.sin(sx*0.018-t*0.42)*6;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*55, 0.13, 1.3, 1.3],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*45, 0.1, 2.1, 0.6],
    [200+Math.sin(t*0.25+6)*110, 220+Math.cos(t*0.45+3)*70, 0.045, 2.8, 1.4]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    cS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.8) * w * 0.5;
  }
  const tw = 7.4;
  const act=aS/tw, inh=iS/tw, cross=cS/tw;
  const bg = (Math.sin(dx*0.035+dy*0.022+t*0.8)+Math.sin(dx*0.028-dy*0.038+t*1.1)+Math.sin(dx*0.02+dy*0.045-t*0.6))/3;
  const turb = (Math.sin((dx+dy)*0.1+t*2.2)*0.5+Math.sin((dx-dy)*0.08-t*1.8)*0.5+Math.sin(dx*0.06+dy*0.07+t*3.1)*0.3)/1.3;
  const dist = Math.sqrt((dx-cx)**2+(dy-cy)**2), ang = Math.atan2(dy-cy, dx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.5)+Math.sin(dist*0.035+ang*4.5-t*1.2)+Math.sin(dist*0.06-ang*2-t*2.0))*0.35;
  const pulse = Math.sin(dist*0.02-t*0.8)*0.3*Math.exp(-dist*0.003);
  const reaction = Math.tanh((act - inh*0.65 + cross*0.3 + bg*0.25 + spiral + turb*0.2 + pulse)*2.0);
  const fine = Math.sin(dx*0.3+t*1.5)*Math.sin(dy*0.3-t*1.2)*0.15;
  const cell = Math.tanh((Math.sin(dx*0.12)*Math.sin(dy*0.12)+Math.sin((dx+dy)*0.08+t)*0.5+Math.sin((dx*2-dy)*0.05-t*0.7)*0.3)*1.5)*0.25;
  const blend = reaction*0.7 + cell*0.2 + fine*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,42,88],[14,78,112],[18,118,128],
    [45,158,135],[120,175,110],[195,185,75],
    [225,155,65],[215,110,72],[185,70,72],
    [140,40,72],[85,22,60],[40,14,50],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const smooth = f*f*(3-2*f);
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.18:0.92+Math.abs(reaction)*0.15;
  const glow = Math.max(0, Math.abs(reaction)-0.5)*0.4;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*smooth)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth)*lum*edge + glow*80)|0)
  ];
}
